// 폼 값을 정리하고, 최종 프롬프트(프롬프트템플릿.md)로 텍스트 생성 요청 본문 4개를 만든다 (Codyssey, OpenAI 호환)
const TEXT_MODEL = "gpt-5.4-mini";
const PROMPTS = {
  "instagram": "너는 인스타그램 캡션 작가야\n주제는 {{ $json.topic }}, 보는 사람은 {{ $json.audience }}, 톤은 {{ $json.tone }}이야\n- 첫 줄: \"더 보기\"를 누르기 전에 읽히는 한 문장. 인사·자기소개 없이 결과나 궁금증으로 시작\n- 본문: 3~5줄, 한 줄에 한 가지 내용\n- 마지막 줄: 저장이나 댓글을 부르는 한 문장\n- 독자를 \"당신\"이라고 부르지 마. 호칭은 생략하거나 친구에게 말하듯\n- 해시태그: 정확히 10개, 넓은 태그와 좁은 태그를 섞어서. 주제나 보는 사람과 관계없는 태그는 넣지 마\n- 절약 시간, 퍼센트, 배수처럼 효과를 나타내는 숫자는 지어내지 마\n- hook_type: 첫 줄에 쓴 훅 기법의 이름만 2~6자 (예: 결과 제시, 질문, 반전)\n- 출력은 올바른 JSON이어야 해. 키와 값은 큰따옴표로 감싸고, 값 안에서 무언가를 인용할 때만 작은따옴표를 써. 값 안의 줄바꿈은 \\n으로 써\n출력은 JSON만: {\"caption\": \"첫 줄\\n본문 1\\n본문 2\\n본문 3\\n마지막 줄\", \"hashtags\": [\"#태그1\", \"#태그2\", \"...\", \"#태그10\"], \"hook_type\": \"훅 이름\"}",
  "blog": "너는 블로그 칼럼 작가야\n주제는 {{ $json.topic }}, 보는 사람은 {{ $json.audience }}, 톤은 {{ $json.tone }}이야\n- 제목: 읽으면 얻는 것을 분명하게, 강조어는 딱 하나\n- 도입: 2~3문장, 인사 없이 독자가 겪는 문제로 시작\n- 본문: 소제목(##) 3개, 소제목마다 2문단\n- 마무리: 핵심을 한 문단으로 정리. 마무리 문단에는 소제목을 붙이지 마. 소제목은 본문의 3개뿐이야\n- 본문 전체 공백 포함 900~1,100자. 1,200자를 넘기지 마\n- 절약 시간, 퍼센트, 배수처럼 효과를 나타내는 숫자는 지어내지 마. 출처, \"~이 최고다\" 같은 단정도 쓰지 마\n- 출력은 올바른 JSON이어야 해. 키와 값은 큰따옴표로 감싸고, 값 안에서 무언가를 인용할 때만 작은따옴표를 써. 값 안의 줄바꿈은 \\n으로 써\n출력은 JSON만: {\"title\": \"제목\", \"body\": \"도입\\n\\n## 소제목 1\\n문단\\n\\n문단\\n\\n## 소제목 2\\n...\\n\\n## 소제목 3\\n...\\n\\n마무리 문단\"}",
  "x": "너는 X(트위터) 카피라이터야\n주제는 {{ $json.topic }}, 톤은 {{ $json.tone }}이야\n- 첫 문장: 인사 없이 결론이나 긴장감으로 시작\n- 핵심 2~3개를 한 문장씩\n- 해시태그 2개 이하\n- 해시태그 포함 전체 120자 이내\n- 절약 시간, 퍼센트, 배수처럼 효과를 나타내는 숫자는 지어내지 마\n- hook_type: 첫 문장에 쓴 훅 기법의 이름만 2~6자 (예: 결론 제시, 질문, 반전)\n- 출력은 올바른 JSON이어야 해. 키와 값은 큰따옴표로 감싸고, 값 안에서 무언가를 인용할 때만 작은따옴표를 써. 값 안의 줄바꿈은 \\n으로 써\n출력은 JSON만: {\"post\": \"게시글\", \"hook_type\": \"훅 이름\"}",
  "image": "너는 SNS 대표 이미지 아트디렉터야\n주제 {{ $json.topic }}로 이미지 생성 AI에 넣을 영어 프롬프트 1개를 써줘\n- 장면 하나, 주인공 하나\n- 장면 묘사 뒤에 Style:, Color:, Composition: 세 부분을 이어서 써. 부분 사이는 \\n으로 구분\n- 이미지 안에 글자, 로고, 실존 브랜드, 캐릭터를 넣지 않기\n- 프롬프트 끝에 반드시 square 1:1, no text, no logos를 넣어\n- 출력은 올바른 JSON이어야 해. 키와 값은 큰따옴표로 감싸고, 값 안에서 무언가를 인용할 때만 작은따옴표를 써. 값 안의 줄바꿈은 \\n으로 써\n출력은 JSON만: {\"image_prompt\": \"장면 묘사\\nStyle: ...\\nColor: ...\\nComposition: ..., square 1:1, no text, no logos\"}"
};

function normalizeInput(form) {
  return {
    topic: String(form['주제'] || form.topic || '').trim(),
    audience: String(form['보는 사람'] || form.audience || '').trim() || '20~30대 직장인',
    tone: String(form['톤'] || form.tone || '').trim() || '친근',
    version: String(form['버전'] || form.version || '').trim() || 'A',
  };
}

function fillPrompt(prompt, input) {
  return prompt
    .split('{{ $json.topic }}').join(input.topic)
    .split('{{ $json.audience }}').join(input.audience)
    .split('{{ $json.tone }}').join(input.tone);
}

function chatBody(prompt, model) {
  return {
    model,
    messages: [{ role: 'user', content: prompt }],
  };
}

const input = normalizeInput($input.first().json);
const bodies = {};
for (const k of Object.keys(PROMPTS)) bodies[k] = chatBody(fillPrompt(PROMPTS[k], input), TEXT_MODEL);
return [{ json: { input, bodies } }];

// 응답을 JSON으로 읽고 기준(글자 수·해시태그·소제목 등)을 검사한다. $runIndex 로 시도 횟수를 센다.
// ───────── 검사 함수 ─────────

// 글자 수: 이모지·한글 모두 1자로 센다 (공백 포함)
function charCount(s) {
  return [...String(s ?? '')].length;
}

// X 가중치 글자 수 (twitter-text v3 기준)
// 라틴·기본 문장부호는 1, 한글·한자·이모지 등은 2, URL은 23. 상한 280.
function xWeightedLength(s) {
  let text = String(s ?? '');
  let weight = 0;
  text = text.replace(/https?:\/\/\S+/g, () => { weight += 23; return ''; });
  for (const ch of text) {
    const c = ch.codePointAt(0);
    const light =
      (c <= 0x10ff) ||
      (c >= 0x2000 && c <= 0x200d) ||
      (c >= 0x2010 && c <= 0x201f) ||
      (c >= 0x2032 && c <= 0x2037);
    weight += light ? 1 : 2;
  }
  return weight;
}

function lines(s) {
  return String(s ?? '').split('\n').map(l => l.trim()).filter(Boolean);
}

function hashtagsIn(s) {
  return String(s ?? '').match(/#[^\s#]+/g) || [];
}

// 확인할 수 없는 통계일 수 있는 표현 (사람이 다시 볼 것)
function numberClaims(s) {
  return String(s ?? '').match(/\d[\d,.]*\s*(%|퍼센트|배|명|만|억|위)/g) || [];
}

function startsWithGreeting(s) {
  return /^(안녕|여러분|반가|오늘은|저는)/.test(lines(s)[0] || '');
}

function check(name, value, target, pass) {
  return { name, value, target, pass };
}

function checkInstagram(d) {
  const caption = d.caption ?? '';
  const tags = Array.isArray(d.hashtags) ? d.hashtags : hashtagsIn(d.hashtags);
  const n = lines(caption).length;
  return [
    check('해시태그 개수', tags.length, '정확히 10', tags.length === 10),
    check('해시태그 형식', tags.filter(t => !/^#[^\s#]+$/.test(t)).join(' ') || '정상', '# + 공백 없음',
      tags.every(t => /^#[^\s#]+$/.test(t))),
    check('캡션 줄 수', n, '5~7 (첫 줄 + 본문 3~5 + 마지막 줄)', n >= 5 && n <= 7),
    check('캡션 안 해시태그', hashtagsIn(caption).length, '0 (hashtags 칸에만)', hashtagsIn(caption).length === 0),
    check('인사로 시작', startsWithGreeting(caption) ? '예' : '아니오', '아니오', !startsWithGreeting(caption)),
    check('수치 표현', numberClaims(caption).join(', ') || '없음', '없음 (있으면 사실 확인)', numberClaims(caption).length === 0),
    check('hook_type', d.hook_type ? '있음' : '없음', '있음', Boolean(d.hook_type)),
  ];
}

function checkBlog(d) {
  const body = d.body ?? '';
  const len = charCount(body);
  const heads = (body.match(/^##\s+\S/gm) || []).length;
  const deeper = (body.match(/^#{3,}\s/gm) || []).length;
  return [
    check('제목', d.title ? charCount(d.title) + '자' : '없음', '있음', Boolean(d.title)),
    check('본문 글자 수(공백 포함)', len, '800~1,200 (미션 500 이상)', len >= 800 && len <= 1200),
    check('미션 기준 500자', len, '500 이상', len >= 500),
    check('소제목(##) 개수', heads, '정확히 3', heads === 3),
    check('### 이하 소제목', deeper, '0', deeper === 0),
    // 출력 형식 예시("마크다운 본문, 소제목은 ##")를 본문에 그대로 베낀 경우
    check('형식 안내문 복사', /마크다운 본문|소제목은 ##/.test(body) ? '있음' : '없음', '없음',
      !/마크다운 본문|소제목은 ##/.test(body)),
    check('인사로 시작', startsWithGreeting(body) ? '예' : '아니오', '아니오', !startsWithGreeting(body)),
    check('수치 표현', numberClaims(body).join(', ') || '없음', '없음 (있으면 사실 확인)', numberClaims(body).length === 0),
  ];
}

function checkX(d) {
  const post = d.post ?? '';
  const len = charCount(post);
  const w = xWeightedLength(post);
  const tags = hashtagsIn(post).length;
  return [
    check('글자 수', len, '120 이하 (미션 280 이하)', len <= 120),
    check('X 실제 가중치', w, '280 이하', w <= 280),
    check('해시태그 개수', tags, '2 이하', tags <= 2),
    check('인사로 시작', startsWithGreeting(post) ? '예' : '아니오', '아니오', !startsWithGreeting(post)),
    check('수치 표현', numberClaims(post).join(', ') || '없음', '없음 (있으면 사실 확인)', numberClaims(post).length === 0),
    check('hook_type', d.hook_type ? '있음' : '없음', '있음', Boolean(d.hook_type)),
  ];
}

function checkImage(d) {
  const p = d.image_prompt ?? '';
  const nonAscii = [...p].filter(ch => ch.codePointAt(0) > 0x7f).length;
  return [
    check('프롬프트', p ? charCount(p) + '자' : '없음', '있음', Boolean(p)),
    check('영어 여부(비ASCII 글자 수)', nonAscii, '0', nonAscii === 0),
    check('정사각형 지시', /1:1|square/i.test(p) ? '있음' : '없음', '있음', /1:1|square/i.test(p)),
    check('글자 금지 지시', /no text|without text|no words|no letters|no typography/i.test(p) ? '있음' : '없음', '있음',
      /no text|without text|no words|no letters|no typography/i.test(p)),
  ];
}

function checkAll(input) {
  const checkers = { instagram: checkInstagram, blog: checkBlog, x: checkX, image: checkImage };
  const result = {};
  for (const [key, fn] of Object.entries(checkers)) {
    if (input[key] == null) continue;
    const checks = fn(input[key]);
    result[key] = { pass: checks.every(c => c.pass), failed: checks.filter(c => !c.pass).map(c => c.name), checks };
  }
  result.allPass = Object.values(result).every(r => r.pass);
  return result;
}

function parseModelJson(content) {
  const s = String(content || '').replace(/```(?:json)?/g, '').trim();
  const start = s.indexOf('{');
  const end = s.lastIndexOf('}');
  return JSON.parse(start >= 0 && end > start ? s.slice(start, end + 1) : s);
}

function evaluate(platform, apiResponse, attempt, maxAttempts) {
  const content = apiResponse && apiResponse.choices && apiResponse.choices[0] && apiResponse.choices[0].message
    ? apiResponse.choices[0].message.content : '';
  let data = null;
  let failed = [];
  let pass = false;
  try {
    data = parseModelJson(content);
    const r = checkAll({ [platform]: data })[platform];
    pass = r.pass;
    failed = r.failed;
  } catch (e) {
    failed = ['JSON 파싱 실패: ' + e.message];
  }
  return { platform, data, pass, failed, attempt, done: pass || attempt >= maxAttempts };
}

return [{ json: evaluate("instagram", $input.first().json, $runIndex + 1, 3) }];

